    /**
     * Handles deleting a Lot entity
     * @param		command ${class.getDeleteCommandAlias()}
     * @return		CompletableFuture<Void>
     */
    @DeleteMapping("/delete")    
    public CompletableFuture<Void> delete( @RequestBody(required=true) DeleteLotCommand command ) {                
    	CompletableFuture<Void> completableFuture = null;
    	try {
        	LotService delegate = service;

        	completableFuture = delegate.delete( command );
    		LOGGER.log( Level.WARNING, "Successfully deleted Lot with key " + command.getLotId() );
        }
        catch( Throwable exc ) {
        	LOGGER.log( Level.WARNING, exc.getMessage() );
        }
        
        return completableFuture;
	}        
	
    /**
     * Handles loading a Lot using a UUID
     * @param		UUID uuid 
     * @return		Lot
     */    
    @GetMapping("/load")
    public Lot load( @RequestParam(required=true) UUID uuid ) {    	
    	Lot entity = null;

    	try {  
    		entity = service.getLot( new LotFetchOneSummary( uuid ) );   
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Lot using Id " + uuid );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Lot business objects
     * @return		Set<Lot>
     */
    @GetMapping("/")
    public List<Lot> loadAll() {                
    	List<Lot> lotList = null;
        
    	try {
            // load the Lot
            lotList = service.getAllLot();
            
            if ( lotList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Lots" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Lots ", exc );
        	return null;
        }

        return lotList;
                            
    }

